INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,tokens)VALUES(v_l_1,v_c_lena,1,'character','Hallo, Raha! Woher kommst du?','سلام رها! اهل کجایی؟',1,'nova/audio/turns/de-fa/A1/s0002/l01/t01.mp3',JSON_ARRAY()),(v_l_1,v_c_raha,2,'learner','Ich komme aus Iran.','من اهل ایران هستم.',1,'nova/audio/turns/de-fa/A1/s0002/l01/t02.mp3',JSON_ARRAY()),(v_l_1,v_c_lena,3,'character','Ah, aus Iran. Ich komme aus Deutschland.','آه، از ایران. من اهل آلمان هستم.',1,'nova/audio/turns/de-fa/A1/s0002/l01/t03.mp3',JSON_ARRAY()),(v_l_1,v_c_raha,4,'learner','Aus Deutschland?','از آلمان؟',1,'nova/audio/turns/de-fa/A1/s0002/l01/t04.mp3',JSON_ARRAY()),(v_l_1,v_c_lena,5,'character','Ja, genau.','بله، دقیقا.',1,'nova/audio/turns/de-fa/A1/s0002/l01/t05.mp3',JSON_ARRAY()),(v_l_1,v_c_raha,6,'learner','Schön!','چه خوب!',1,'nova/audio/turns/de-fa/A1/s0002/l01/t06.mp3',JSON_ARRAY()),(v_l_1,v_c_lena,7,'character','Sprichst du Deutsch?','آلمانی صحبت می‌کنی؟',1,'nova/audio/turns/de-fa/A1/s0002/l01/t07.mp3',JSON_ARRAY()),(v_l_1,v_c_raha,8,'learner','Ein bisschen.','یک کم.',1,'nova/audio/turns/de-fa/A1/s0002/l01/t08.mp3',JSON_ARRAY());INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,tokens)VALUES(v_l_2,v_c_lena,1,'character','Woher kommst du, Raha?','رها، اهل کجایی؟',1,'nova/audio/turns/de-fa/A1/s0002/l02/t01.mp3',JSON_ARRAY()),(v_l_2,v_c_raha,2,'learner','Ich komme aus Iran.','من اهل ایران هستم.',1,'nova/audio/turns/de-fa/A1/s0002/l02/t02.mp3',JSON_ARRAY()),(v_l_2,v_c_lena,3,'character','Welche Sprachen sprichst du?','چه زبان‌هایی صحبت می‌کنی؟',1,'nova/audio/turns/de-fa/A1/s0002/l02/t03.mp3',JSON_ARRAY()),(v_l_2,v_c_raha,4,'learner','Ich spreche Persisch.','من فارسی صحبت می‌کنم.',1,'nova/audio/turns/de-fa/A1/s0002/l02/t04.mp3',JSON_ARRAY()),(v_l_2,v_c_lena,5,'character','Und Deutsch?','و آلمانی؟',1,'nova/audio/turns/de-fa/A1/s0002/l02/t05.mp3',JSON_ARRAY()),(v_l_2,v_c_raha,6,'learner','Ich spreche ein bisschen Deu