,v_c_lena,3,'character','Freut mich. Woher kommst du?','خوشحالم. اهل کجایی؟',1,'nova/audio/turns/de-fa/A1/s0002/l04/t03.mp3',JSON_ARRAY()),(v_l_4,v_c_raha,4,'learner','Ich komme aus Iran.','من اهل ایران هستم.',1,'nova/audio/turns/de-fa/A1/s0002/l04/t04.mp3',JSON_ARRAY()),(v_l_4,v_c_lena,5,'character','Sprichst du Persisch und Deutsch?','فارسی و آلمانی صحبت می‌کنی؟',1,'nova/audio/turns/de-fa/A1/s0002/l04/t05.mp3',JSON_ARRAY()),(v_l_4,v_c_raha,6,'learner','Persisch, ja. Deutsch nur ein bisschen.','فارسی، بله. آلمانی فقط یک کم.',1,'nova/audio/turns/de-fa/A1/s0002/l04/t06.mp3',JSON_ARRAY()),(v_l_4,v_c_lena,7,'character','Dann üben wir Deutsch zusammen.','پس با هم آلمانی تمرین می‌کنیم.',1,'nova/audio/turns/de-fa/A1/s0002/l04/t07.mp3',JSON_ARRAY()),(v_l_4,v_c_raha,8,'learner','Gern!','با کمال میل!',1,'nova/audio/turns/de-fa/A1/s0002/l04/t08.mp3',JSON_ARRAY());
