INSERT IGNORE INTO sem_lesson_learning_units(lesson_id,learning_unit_id,learning_role,is_target,exposure_count)SELECT v_l_1,id,'new',1,2 FROM sem_learning_units WHERE course_id=v_course AND unit_key IN('de:a1:ich-komme-aus','de:a1:woher-kommst-du','de:a1:ich-spreche','de:a1:ein-bisschen-deutsch','de:a1:verb-position-1','de:a1:pron:ich-laut','de:a1:can:origin-language');
INSERT IGNORE INTO sem_lesson_learning_units(lesson_id,learning_unit_id,learning_role,is_target,exposure_count)SELECT v_l_4,id,'mastery',1,1 FROM sem_learning_units WHERE course_id=v_course AND unit_key IN('de:a1:ich-komme-aus','de:a1:woher-kommst-du','de:a1:ich-spreche','de:a1:ein-bisschen-deutsch','de:a1:verb-position-1','de:a1:pron:ich-laut','de:a1:can:origin-language');
INSERT IGNORE INTO sem_turn_learning_units(turn_id,learning_unit_id,evidence_type)SELECT t.id,lu.id,'mastery' FROM turns t JOIN sem_learning_units lu ON lu.course_id=v_course AND lu.unit_key IN('de:a1:ich-komme-aus','de:a1:woher-kommst-du','de:a1:ich-spreche','de:a1:ein-bisschen-deutsch','de:a1:verb-position-1','de:a1:pron:ich-laut','de:a1:can:origin-language') WHERE t.lesson_id=v_l_4 AND t.sort_order=2;
INSERT IGNORE INTO sem_review_obligations(course_id,learning_unit_id,origin_chapter_id,due_series,spacing_offset,status)SELECT v_course,lu.id,v_chapter,2+o.off,o.off,'due' FROM sem_learning_units lu JOIN(SELECT 1 off UNION ALL SELECT 2 UNION ALL SELECT 4 UNION ALL SELECT 8 UNION ALL SELECT 16)o WHERE lu.course_id=v_course AND lu.unit_key IN('de:a1:ich-komme-aus','de:a1:woher-kommst-du','de:a1:ich-spreche','de:a1:ein-bisschen-deutsch','de:a1:verb-position-1','de:a1:pron:ich-laut','de:a1:can:origin-language');
