-- SERIES 2
SET NAMES utf8mb4;
DROP PROCEDURE IF EXISTS nova_de_v32_s0002;
DELIMITER $$
CREATE PROCEDURE nova_de_v32_s0002()
BEGIN
DECLARE v_count INT DEFAULT 0;DECLARE v_course BIGINT UNSIGNED;DECLARE v_level BIGINT UNSIGNED;DECLARE v_module BIGINT UNSIGNED;DECLARE v_chapter BIGINT UNSIGNED;DECLARE v_c_raha BIGINT UNSIGNED;DECLARE v_c_lena BIGINT UNSIGNED;DECLARE v_l_1 BIGINT UNSIGNED;DECLARE v_l_2 BIGINT UNSIGNED;DECLARE v_l_3 BIGINT UNSIGNED;DECLARE v_l_4 BIGINT UNSIGNED;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK;RESIGNAL;END;
START TRANSACTION;
SELECT COUNT(*),MIN(id) INTO v_count,v_course FROM courses WHERE learning_language='de' AND base_language='fa';IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='de-fa course identity missing or not unique';END IF;
SELECT COUNT(*),MIN(id) INTO v_count,v_level FROM levels WHERE course_id=v_course AND cefr_level='A1';IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='de-fa A1 missing or not unique';END IF;
SELECT COUNT(*),MIN(id) INTO v_count,v_module FROM modules WHERE level_id=v_level AND sort_order=1;IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='de-fa module 1 missing or not unique';END IF;
SELECT id INTO v_c_raha FROM characters WHERE course_id=v_course AND name='Raha' AND gender='female' LIMIT 1;SELECT id INTO v_c_lena FROM characters WHERE course_id=v_course AND name='Lena' AND gender='female' LIMIT 1;
SELECT COUNT(*),MIN(id) INTO v_count,v_chapter FROM chapters WHERE module_id=v_module AND sort_order=2;
IF v_count=0 THEN
ON DUPLICATE KEY UPDATE display_form=VALUES(display_form);
SELECT id INTO v_l_1 FROM lessons WHERE chapter_id=v_chapter AND sort_order=1 LIMIT 1;SELECT id INTO v_l_2 FROM lessons WHERE chapter_id=v_chapter AND sort_order=2 LIMIT 1;SELECT id INTO v_l_3 FROM lessons WHERE chapter_id=v_chapter AND sort_order=3 LIMIT 1;SELECT id INTO v_l_4 FROM lessons WHERE chapter_id=v_chapter AND sort_order=4 LIMIT 1;
UPDATE sem_review_obligations ro JOIN activities a ON a.lesson_id=v_l_3 AND a.sort_order=12 SET ro.status='fulfilled',ro.fulfilled_chapter_id=v_chapter,ro.evidence_activity_id=a.id WHERE ro.course_id=v_course AND ro.due_series=2 AND ro.status='due';
END IF;COMMIT;END$$
DELIMITER ;
CALL nova_de_v32_s0002();
DROP PROCEDURE IF EXISTS nova_de_v32_s0002;
